local base = piece("base")
local lthigh = piece("lthigh")
local lshin = piece("lshin")
local rthigh = piece("rthigh")
local rshin = piece("rshin")
local armbase = piece("armbase")
local arm = piece("arm")
local arm2 = piece("arm2")
local door = piece("door")

local SIG_WALK_BIPED = 1
local SIG_BUILDARM = 4
local SIG_OPEN_CLOSE = 8

-- Walk, two legs
local function walk()
  SetSignalMask(SIG_WALK_BIPED)
  while true do
    Turn(lthigh, x_axis, 0.415, 2.075)
    Turn(lshin, x_axis, 0.1809, 0.9045)
    Turn(rthigh, x_axis, -0.415, 2.075)
    Turn(rshin, x_axis, 0.3427, 0.9045)
    Sleep(198)
    Turn(lthigh, x_axis, 0.2565, 0.7925)
    Turn(lshin, x_axis, 0.4736, 1.4635)
    Turn(rthigh, x_axis, -0.2565, 0.7925)
    Turn(rshin, x_axis, 0.05, 1.4635)
    Sleep(198)
    Turn(lthigh, x_axis, -0.2565, 2.565)
    Turn(rthigh, x_axis, 0.2565, 2.565)
    Sleep(198)
    Turn(lthigh, x_axis, -0.415, 0.7925)
    Turn(lshin, x_axis, 0.1809, 1.4635)
    Turn(rthigh, x_axis, 0.415, 0.7925)
    Turn(rshin, x_axis, 0.3427, 1.4635)
    Sleep(198)
    Turn(lthigh, x_axis, 0, 2.075)
    Turn(lshin, x_axis, 0, 0.9045)
    Turn(rthigh, x_axis, 0, 2.075)
    Turn(rshin, x_axis, 0.5236, 0.9045)
    Sleep(198)
  end
end

local function walkStop()
  Turn(lthigh, x_axis, 0, 4)
  Turn(lshin, x_axis, 0, 4)
  Turn(rthigh, x_axis, 0, 4)
  Turn(rshin, x_axis, 0, 4)
end

