    Turn(arm, x_axis, -0.1745, 0.7053)
    Turn(arm2, x_axis, -0.1745, 0.7053)
    Sleep(330)
    Turn(armbase, y_axis, 0.2089, 0.9603)
    Turn(arm, x_axis, -0.328, 0.4605)
    Turn(arm2, x_axis, -0.328, 0.4605)
    Sleep(330)
    Turn(armbase, y_axis, -0.2089, 1.2534)
    Sleep(330)
    Turn(armbase, y_axis, -0.529, 0.9603)
    Turn(arm, x_axis, -0.1745, 0.4605)
    Turn(arm2, x_axis, -0.1745, 0.4605)
    Sleep(330)
    Turn(armbase, y_axis, -0.6016, 0.2178)
    Turn(arm, x_axis, 0.0606, 0.7053)
    Turn(arm2, x_axis, 0.0606, 0.7053)
    Sleep(330)
    Turn(armbase, y_axis, -0.3927, 0.6267)
